# Hugging Face repo, file, SHA-256 (the LFS object id).
MODELS=(
  "unsloth/gemma-4-E2B-it-GGUF gemma-4-E2B-it-Q4_K_M.gguf 740185b21d22ceb83a11c3aa62ad5842ef32c70f6096d756bbee85a1e4ec34b8"
  "unsloth/gemma-4-E4B-it-GGUF gemma-4-E4B-it-Q4_K_M.gguf 85a896a047553e842f25297ee5b031d64ff30147d9c4af17b1e4b394cd1fab87"
  "unsloth/gemma-4-26B-A4B-it-GGUF gemma-4-26B-A4B-it-UD-Q4_K_M.gguf f2c28b3dc4776931ac6f879e11f203dec637ea0f14267a86ec8f6165f63f293f"
)

# ── helpers ───────────────────────────────────────────────────────────────

now() { date +%s.%N; }
# secs START END: seconds between two epoch times, one decimal.
secs() { awk -v a="$1" -v b="$2" 'BEGIN { printf "%.1f", b - a }'; }
# iso_epoch TIMESTAMP: epoch seconds of an RFC 3339 timestamp; nothing for an empty or bad one.
iso_epoch() { [[ -n $1 ]] && date -d "$1" +%s.%N 2>/dev/null || true; }
uri() { jq -rn --arg s "$1" '$s | @uri'; }
api() { curl -fsS --max-time 10 "$API/api/v1/$1"; }
api_up() { curl -fsS -o /dev/null --max-time 3 "$API/api/v1/sessions" 2>/dev/null; }
messages() { api "sessions/$(uri "$1")/messages?from=0&limit=1000"; }
new_nonce() { printf 'spk%s' "$(od -An -N4 -tx4 /dev/urandom | tr -d ' \n')"; }

# need_api: true when the unit's API answers; otherwise says which stage to finish first.
need_api() {
  api_up && return 0
  warn "agentsview isn't answering on $API: finish the \"Start the sandboxed unit\" stage first"
  return 1
}

# prompt "text" shows a prompt to send in an agent, and copies it when a clipboard tool exists.
prompt() {
  printf '\n    %s%s%s\n\n' "$BOLD" "$1" "$RESET"
  if command -v wl-copy >/dev/null 2>&1 && [[ -n ${WAYLAND_DISPLAY:-} ]]; then
    printf '%s' "$1" | wl-copy && note "(copied to the clipboard)"
  elif command -v xclip >/dev/null 2>&1 && [[ -n ${DISPLAY:-} ]]; then
    printf '%s' "$1" | xclip -selection clipboard && note "(copied to the clipboard)"
  fi
  return 0
}

# record KEY TEXT: one section of results.md per key, rebuilt from all sections in key order.
record() {
  mkdir -p "$SPIKE_DIR/results.d"
  printf '%s\n' "$2" >"$SPIKE_DIR/results.d/$1.md"
  {
    printf '# agent-fabric phase 0 results\n\n'
    printf 'Timings, counts and settings only, no session text. Generated by scripts/spike/phase0.sh.\n\n'
    cat "$SPIKE_DIR"/results.d/*.md
  } >"$SPIKE_DIR/results.md"
}

# done_before N: true when stage N finished on an earlier run and the human skips it.
done_before() {
  local k="DONE_$1"
  [[ -n ${!k:-} ]] && confirm "Finished on ${!k}. Skip it?"
}

# run_stage N TITLE FUNCTION: announce the stage, offer a skip, mark it done when it succeeds.
run_stage() {
  stage "$2"
  if done_before "$1"; then return 0; fi
  if "$3"; then
    write_env "DONE_$1" "$(date '+%Y-%m-%d %H:%M')" >/dev/null
  else
    warn "stage not finished; re-run the wizard to retry it"
    pause "Press Enter to go on"
  fi
}

BG_PIDS=()
# bg_start CMD...: run a recorder in the background until bg_stop.
bg_start() {
  "$@" </dev/null >/dev/null 2>&1 &
  BG_PIDS+=("$!")
}
bg_stop() {
  local p
  for p in "${BG_PIDS[@]}"; do
    pkill -TERM -P "$p" 2>/dev/null || true
    kill "$p" 2>/dev/null || true
  done
  if ((${#BG_PIDS[@]})); then wait "${BG_PIDS[@]}" 2>/dev/null || true; fi
  BG_PIDS=()
}
trap bg_stop EXIT

sctl() { if [[ ${UNIT_MODE:-} == user ]]; then systemctl --user "$@"; else systemctl "$@"; fi; }
jctl() { if [[ ${UNIT_MODE:-} == user ]]; then journalctl --user -u agentsview "$@"; else journalctl -u agentsview "$@"; fi; }

# copilot_sync_off: true when Copilot CLI won't sync sessions: remoteExport false and remoteSessions
# not true (§7). Falls back to text matching when the file has comments.
copilot_sync_off() {
  local f=$COPILOT_SETTINGS
  [[ -s $f ]] || return 1
  if jq empty "$f" 2>/dev/null; then
    jq -e '.remoteExport == false and .remoteSessions != true' "$f" >/dev/null 2>&1
  else
    grep -Eq '"remoteExport"[[:space:]]*:[[:space:]]*false' "$f" && ! grep -Eq '"remoteSessions"[[:space:]]*:[[:space:]]*true' "$f"
  fi
}

# cursor_db_mode: journal mode of Cursor's state.vscdb, from its header (bytes 18-19 are 2 in WAL mode).
cursor_db_mode() {
  [[ -f $CURSOR_DB ]] || {
    echo "not found"
    return 0
  }
  od -An -tu1 -j18 -N2 "$CURSOR_DB" | awk '{ print ($1 == 2 && $2 == 2) ? "wal" : "rollback" }'
}

# find_session AGENT NONCE: id of the agent's recent session whose first message contains NONCE.
find_session() {
  local list id
  list=$(api "sessions?agent=$1&include_one_shot=true&limit=10") || return 1
  id=$(jq -r --arg n "$2" 'first(.sessions[] | select((.first_message // "") | contains($n)) | .id) // empty' <<<"$list")
  if [[ -z $id ]]; then
    # first_message may be cut short; look through the newest sessions' messages instead.
    for id in $(jq -r '.sessions[:5][].id' <<<"$list"); do
      if messages "$id" | jq -e --arg n "$2" 'any(.messages[]; .role == "user" and (.content | contains($n)))' >/dev/null; then
        printf '%s\n' "$id"
        return 0
      fi
    done
    return 1
  fi
  printf '%s\n' "$id"
}

# wait_for_session AGENT NONCE TIMEOUT: find_session, retried every half second.
wait_for_session() {
  local end=$(($(date +%s) + $3)) id
  while (($(date +%s) < end)); do
    if id=$(find_session "$1" "$2"); then
      printf '%s\n' "$id"
      return 0
    fi
    sleep 0.5
  done
  return 1
}

# message_ts SID ROLE NONCE: epoch of the first ROLE message containing NONCE, from the message's
# own timestamp; nothing when it has none.
message_ts() {
  iso_epoch "$(messages "$1" | jq -r --arg r "$2" --arg n "$3" \
    'first(.messages[] | select(.role == $r and (.content | contains($n))) | .timestamp // "") // ""' 2>/dev/null || true)"
}

# poll_nonce SID NONCE TIMEOUT: prints "ROLE ARRIVED STAMPED" when the user message and then the
# assistant message containing NONCE first show up in the API. ARRIVED is when this poll saw it,
# STAMPED the message's own timestamp (empty when it has none).
poll_nonce() {
  local end=$(($(date +%s) + $3)) user="" body hit role
  while (($(date +%s) < end)); do
    if body=$(messages "$1"); then
      for role in user assistant; do
        [[ $role == user && -n $user ]] && continue
        hit=$(jq -r --arg r "$role" --arg n "$2" \
          'first(.messages[] | select(.role == $r and (.content | contains($n))) | "hit " + (.timestamp // "")) // empty' <<<"$body")
        [[ -n $hit ]] || continue
        echo "$role $(now) $(iso_epoch "${hit#hit }")"
        [[ $role == user ]] && user=1
        [[ $role == assistant ]] && return 0
      done
    fi
    sleep 0.5
  done
  return 1
}

# Recorders for one test session: `session watch` events, /api/v1/events and message snapshots,
# each line or file stamped with the time it arrived.
rec_watch() {
  "$BIN" session watch "$1" --server "$API" 2>>"$2.err" |
    while IFS= read -r line; do printf '%s %s\n' "$(now)" "$line"; done >>"$2"
}
rec_events() {
  curl -sN "$API/api/v1/events" |
    while IFS= read -r line; do [[ -z $line ]] || printf '%s %s\n' "$(now)" "$line"; done >>"$1"
}
rec_snapshots() {
  local last="" body h
  mkdir -p "$2"
  while :; do
    if body=$(messages "$1"); then
      h=$(printf '%s' "$body" | sha256sum | cut -c1-16)
      if [[ $h != "$last" ]]; then
        printf '%s\n' "$body" >"$2/$(now).json"
        last=$h
      fi
    fi
    sleep 2
  done
}

# quiet_wait WATCHLOG: wait until the session has had no update for 5 s (at most 60 s), so the
# next round's watch event can't be a late update from the previous turn.
quiet_wait() {
  local end=$(($(date +%s) + 60)) last
  while (($(date +%s) < end)); do
    last=$(awk '/session_updated/ { t = $1 } END { print t + 0 }' "$1")
    awk -v l="$last" -v n="$(now)" 'BEGIN { exit !(n - l >= 5) }' && return 0
    sleep 1
  done
  return 0
}

# lag_round SID NONCE WATCHLOG: one timed prompt. Sets LAG_USER and LAG_REPLY (API arrival minus
# the message's own timestamp, or minus the Enter key press when there is none; LAG_ENTER=1 then),
# and LAG_WATCH (first session_updated event at or after the prompt's timestamp).
lag_round() {
  local out t0 tu mu ta ma base
  note "waiting for the session to go quiet…"
  quiet_wait "$3"
  step "Send exactly:"
  prompt "Reply with exactly $2 and nothing else."
  pause "Press Enter here, then send it straight away"
  t0=$(now)
  note "waiting for the prompt and the reply to show up in agentsview (up to 3 min)…"
  out=$(mktemp)
  poll_nonce "$1" "$2" 180 >"$out" || true
  read -r tu mu < <(awk '$1 == "user" { print $2, $3 }' "$out") || true
  read -r ta ma < <(awk '$1 == "assistant" { print $2, $3 }' "$out") || true
  rm -f "$out"
  if [[ -z ${tu:-} ]]; then
    LAG_USER=">180"
  elif [[ -n ${mu:-} ]]; then
    LAG_USER=$(secs "$mu" "$tu")
  else
    LAG_USER=$(secs "$t0" "$tu") LAG_ENTER=1
  fi
  if [[ -z ${ta:-} ]]; then
    LAG_REPLY=">180"
  elif [[ -n ${ma:-} ]]; then
    LAG_REPLY=$(secs "$ma" "$ta")
  else
    LAG_REPLY="no timestamp"
  fi
  base=${mu:-$t0}
  LAG_WATCH=$(awk -v t="$base" '$1 + 0 >= t + 0 && /session_updated/ { printf "%.1f", $1 - t; found = 1; exit }
    END { if (!found) print "none" }' "$3")
  say "prompt captured after ${LAG_USER} s · first watch event ${LAG_WATCH} s · reply captured after ${LAG_REPLY} s"
}

# max_of VALUES...: largest number, or the first non-number (">180", "none") if there is one.
max_of() {
  printf '%s\n' "$@" | awk '!/^-?[0-9.]+$/ { bad = $0; exit } { if (n++ == 0 || $1 > m) m = $1 }
    END { if (bad != "") print bad; else printf "%.1f", m }'
}

# tool_rows MESSAGES_JSON: one TSV row per tool call: ordinal, tool, category, result status,
# exit code found in the result, whether the result has error text.
tool_rows() {
  jq -r '
    .messages[] | .ordinal as $o | .tool_calls[]? | (.result_content // "") as $r |
    [ $o, .tool_name, (.category // ""),
      ([.result_events[]?.status | select(. != "")] | unique | join(",")),
      (first($r | capture("(exit(ed)?( with)? code|exit status|exit[ _]code\"?:?)\\s*(?<c>-?[0-9]+)"; "i") | .c) // ""),
      (if ($r | test("traceback|failed|patch did not apply|permission denied|error:|could not find|did not find|not found in"; "i")) then "yes" else "" end)
    ] | @tsv' "$1"
}

# failing_command / failed_edit ROWS: the first matching tool call, by agentsview's category; the
# tool name only counts when the category says nothing (Other, Tool or empty).
failing_command() {
  awk -F'\t' '($3 == "Bash" || (($3 == "" || $3 == "Other" || $3 == "Tool") && tolower($2) ~ /terminal|shell|command|exec/)) &&
    (($5 != "" && $5 != "0") || $6 == "yes") { print $2 " (exit " ($5 == "" ? "?" : $5) ")"; exit }' <<<"$1"
}
failed_edit() {
  awk -F'\t' '($3 == "Edit" || $3 == "Write" || (($3 == "" || $3 == "Other" || $3 == "Tool") && tolower($2) ~ /edit|replace|patch|write_file|create_file/)) &&
    ($4 ~ /error/ || $6 == "yes") { print $2 " (" ($4 ~ /error/ ? "status " $4 : "error text") ")"; exit }' <<<"$1"
}

# agent_session KEY LABEL AGENT HOW: one test session in an agent (§9 items 1, 2, 4 and 7).
agent_session() {
  local key=$1 label=$2 agent=$3 how=$4 dir n0 n1 n2 sid t0 tf m0 lag_first basis
  local u1 r1 w1 u2 r2 w2 rows cmd_hit edit_hit confirmed snaps tool_summary="0" tool_list="(none)"
  need_api || return 1
  if [[ -z ${SCRATCH_DIR:-} ]]; then
    warn "run the scratch project stage first"
    return 1
  fi
  # Fresh tags on every attempt, so a retry can't match the previous attempt's session.
  n0=$(new_nonce) n1=$(new_nonce) n2=$(new_nonce)
  write_env "CAPTURED_$key" no >/dev/null
  write_env "SID_$key" "" >/dev/null
  write_env "NONCE_$key" "$n0" >/dev/null
  dir=$REC/$key/$(date +%Y%m%d-%H%M%S)
  mkdir -p "$dir"
  say "$how"
  step "Start a new chat in agent mode and send exactly:"
  prompt "Hi, this is a capture test ($n0). Reply with one short sentence."
  pause "Press Enter here, then send it straight away"
  t0=$(now)
  note "waiting for agentsview to capture it (up to 5 min)…"
  if ! sid=$(wait_for_session "$agent" "$n0" 300); then
    warn "$label: not captured within 5 min"
    record "20-$key" "## $label ($agent)

Not captured within 5 min of sending the first prompt. Check \`journalctl\` for agentsview errors
and whether the sandbox hides the agent's files (\`agentsview doctor\`).
"
    return 1
  fi
  tf=$(now)
  write_env "SID_$key" "$sid"
  write_env "CAPTURED_$key" yes
  LAG_ENTER=""
  m0=$(message_ts "$sid" user "$n0")
  if [[ -n $m0 ]]; then lag_first=$(secs "$m0" "$tf"); else lag_first=$(secs "$t0" "$tf") LAG_ENTER=1; fi
  say "captured as $sid after $lag_first s"

  : >"$dir/watch.log"
  bg_start rec_watch "$sid" "$dir/watch.log"
  bg_start rec_events "$dir/events.log"
  bg_start rec_snapshots "$sid" "$dir/snapshots"
  lag_round "$sid" "$n1" "$dir/watch.log" && u1=$LAG_USER r1=$LAG_REPLY w1=$LAG_WATCH
  lag_round "$sid" "$n2" "$dir/watch.log" && u2=$LAG_USER r2=$LAG_REPLY w2=$LAG_WATCH
  if [[ -n $LAG_ENTER ]]; then
    basis="the Enter key press (some messages have no timestamp), so these include your own delay"
  else
    basis="each message's own timestamp"
  fi

  step "Now send this (approve the command if the agent asks):"
  prompt "Run python3 -m unittest -q in this folder with your terminal tool and tell me the exit code. Don't change any files."
  pause "Press Enter when the agent has finished"
  step "Then send:"
  prompt "Without reading calc.py first, call your file edit tool once to replace the exact text RATE = 0.25 with RATE = 0.3 in calc.py. If the edit fails, report the error and stop: don't retry, don't read the file, don't create anything."
  pause "Press Enter when the agent has finished"
  note "letting capture settle for 15 s…"
  sleep 15
  bg_stop
  api "sessions/$(uri "$sid")" >"$dir/session.json" || true
  messages "$sid" >"$dir/messages.json" || true
  api "sessions/$(uri "$sid")/tool-calls" >"$dir/tool-calls.json" || true
  snaps=$(find "$dir/snapshots" -name '*.json' 2>/dev/null | wc -l || true)

  rows=$(tool_rows "$dir/messages.json" 2>/dev/null || true)
  cmd_hit=$(failing_command "$rows")
  edit_hit=$(failed_edit "$rows")
  if [[ -n $rows ]]; then
    tool_summary=$(awk -F'\t' '{ n++; c[$3 == "" ? "?" : $3]++ } END { s = ""; for (k in c) s = s (s == "" ? "" : ", ") k " " c[k]; print n " (" s ")" }' <<<"$rows")
    tool_list=$(awk -F'\t' '{ printf "#%s %s %s status=%s exit=%s error-text=%s\n", $1, $2, ($3 == "" ? "-" : $3), ($4 == "" ? "-" : $4), ($5 == "" ? "-" : $5), ($6 == "" ? "no" : $6) }' <<<"$rows")
  fi
  say "tool calls captured:"
  printf '%s\n' "$tool_list" | sed 's/^/    /'
  say "failing command detected: ${cmd_hit:-no}"
  say "failed edit detected: ${edit_hit:-no}"
  if confirm "In $label, did the agent really run the tests (they fail) and try the edit (it fails)?"; then
    confirmed=yes
  else
    confirmed="no: the agent didn't do both, so a 'no' above may be the agent, not agentsview"
  fi
  write_env "LAG_${key}" "$(max_of "$lag_first" "$u1" "$u2")"
  write_env "WATCH_${key}" "$(max_of "$w1" "$w2")"
  write_env "FAILCMD_${key}" "${cmd_hit:+yes}"
  write_env "FAILEDIT_${key}" "${edit_hit:+yes}"
  record "20-$key" "## $label ($agent)

| Check | Result |
|---|---|
| Captured | yes, \`$sid\` |
| Capture lag, first prompt | $lag_first s |
| Capture lag, prompts (rounds 1, 2) | $u1 s, $u2 s |
| First \`session watch\` event after the prompt | $w1 s, $w2 s |
| Capture lag, replies (from the reply's timestamp, which may be when it started) | $r1 s, $r2 s |
| Lags measured from | $basis |
| Failing command detected | ${cmd_hit:-no} |
| Failed edit detected | ${edit_hit:-no} |
| You saw the agent do both | $confirmed |
| Tool calls | $tool_summary |
| Recordings | \`$dir\`: $snaps message snapshots, watch.log, events.log |

Tool calls (ordinal, tool, category, status, exit code, error text):

\`\`\`text
$tool_list
\`\`\`
"
  pause "Press Enter to go on"
}

# unit_file: the sandboxed unit for UNIT_MODE (§4.1). Absolute paths, so it also works as a system
# unit, where %h would be root's home.
unit_file() {
  local p i
  printf '[Unit]\nDescription=agentsview session capture for agent-fabric (sandboxed)\n\n[Service]\n'
  [[ ${UNIT_MODE:-} == system ]] && printf 'User=%s\n' "$USER"
  printf 'ExecStart=%s serve --no-browser --no-update-check --port %s --replace\n' "$BIN" "$AV_PORT"
  printf 'Environment=AGENTSVIEW_TELEMETRY_ENABLED=0\nRestart=on-failure\nRestartSec=30\n'
  for ((i = 1; i < ${#SANDBOX_PROPS[@]}; i += 2)); do printf '%s\n' "${SANDBOX_PROPS[i]}"; done
  printf 'ReadWritePaths=%s/.agentsview\n' "$HOME"
  for p in "$HOME/.ssh" "$HOME/.gnupg" "$HOME/.config/gh" "$HOME/.codex/auth.json"; do
    printf 'InaccessiblePaths=-%s\n' "$p"
  done
  if [[ -s $SPIKE_DIR/inaccessible.txt ]]; then
    while IFS= read -r p; do printf 'InaccessiblePaths=-%s\n' "$p"; done <"$SPIKE_DIR/inaccessible.txt"
  fi
  printf '\n[Install]\n'
  if [[ ${UNIT_MODE:-} == system ]]; then printf 'WantedBy=multi-user.target\n'; else printf 'WantedBy=default.target\n'; fi
}

# loopback_server: a throwaway HTTP server on 127.0.0.1 for the loopback probe; prints its pid.
loopback_server() {
  local root
  root=$(mktemp -d)
  python3 -m http.server "$PROBE_PORT" --bind 127.0.0.1 --directory "$root" </dev/null >/dev/null 2>&1 &
  echo "$!"
  sleep 1
}

# agent_counts: "agent n" per agent, as agentsview sees them now.
agent_counts() {
  local a
  for a in codex copilot vscode-copilot cursor-ide; do
    printf '%s %s\n' "$a" "$(api "sessions?agent=$a&include_one_shot=true&limit=1" | jq -r '.total // 0' 2>/dev/null || echo '?')"
  done
}

# stray_daemons: agentsview processes outside the unit other than MCP proxies (§8: an MCP client
# can start its own unconfined daemon when --server is missing).
stray_daemons() {
  local pid cg cmd
  for pid in $(pgrep -x agentsview || true); do
    cg=$(cat "/proc/$pid/cgroup" 2>/dev/null || true)
    cmd=$(tr '\0' ' ' <"/proc/$pid/cmdline" 2>/dev/null || true)
    if ! in_unit_cgroup "$cg" && [[ $cmd != *" mcp "* && $cmd != *" mcp" ]]; then
      printf '%s %s\n' "$pid" "$cmd"
    fi
  done
}

# in_unit_cgroup CGROUP: true for the cgroup of this UNIT_MODE's unit; a unit of the other mode, left
# from an earlier run, counts as outside.
in_unit_cgroup() {
  if [[ ${UNIT_MODE:-} == user ]]; then
    [[ $1 == */user@*.service/*agentsview.service* ]]
  else
    [[ $1 == */system.slice/agentsview.service* ]]
  fi
}

# bindable PORT: true when 127.0.0.1:PORT can be bound now, the way agentsview binds it.
bindable() {
  python3 -I -c '
import socket, sys
s = socket.socket()
s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
try:
    s.bind(("127.0.0.1", int(sys.argv[1])))
except OSError:
    sys.exit(1)' "$1"
}

# port_holders PORT [SKIP_PID]: what keeps the unit off 127.0.0.1:PORT, as "pid name" lines ("? ?"
# when ss can't name it, such as another user's process); nothing when the port is free or only
# SKIP_PID holds it. Listeners on other addresses (::1, a LAN or Tailscale IP) don't count.
port_holders() {
  local all
  bindable "$1" && return 0
  all=$(ss -Hltnp "sport = :$1" 2>/dev/null | awk '{
    l = $4; sub(/:[0-9]+$/, "", l); sub(/%.*/, "", l)
    if (l !~ /^(127\.0\.0\.1|0\.0\.0\.0|\*|\[::\]|\[::ffff:127\.0\.0\.1\]|\[::ffff:0\.0\.0\.0\])$/) next
    s = $0; n = 0
    while (match(s, /\("[^"]+",pid=[0-9]+/)) {
      split(substr(s, RSTART + 2, RLENGTH - 2), a, "\",pid=")
      print a[2], a[1]; n++
      s = substr(s, RSTART + RLENGTH)
    }
    if (!n) print "? ?"
  }' | sort -u)
  awk -v skip="${2:-}" '$1 != skip' <<<"${all:-? ?}"
}

# pick_port: sets AV_PORT and API for the unit. Keeps AV_PORT when it's free or only the unit holds it
# (the unit restarts); otherwise offers the next free one. Without --port agentsview moves to the
# next free port by itself, so the unit passes --port to fail instead.
pick_port() {
  local p=$AV_PORT q last unit_pid held
  # No leading zero (bash would read it as octal) and at most 5 digits (no overflow), then the range.
  if ! [[ $p =~ ^[1-9][0-9]{3,4}$ ]] || ((p < 1024 || p > 65535)); then
    warn "AV_PORT=$p in $ENV_FILE isn't a port from 1024 to 65535"
    return 1
  fi
  unit_pid=$(sctl show -p MainPID --value agentsview.service 2>/dev/null || true)
  held=$(port_holders "$p" "$unit_pid")
  if [[ -n $held ]]; then
    warn "port $p is taken by: $(paste -sd ',' - <<<"$held" | sed 's/,/, /g') (pid name)"
    last=$((p + 99 > 65535 ? 65535 : p + 99))
    for ((q = p + 1; q <= last; q++)); do
      [[ -z $(port_holders "$q" "$unit_pid") ]] && break
    done
    if ((q > last)); then
      warn "no free port after $p up to $last: free port $p, or set AV_PORT=<port> in $ENV_FILE and re-run"
      return 1
    fi
    if ! confirm "Run agentsview on port $q instead (the unit gets --port $q, Codex's MCP --server)"; then
      note "free port $p, or set AV_PORT=<port> in $ENV_FILE, then re-run"
      return 1
    fi
    if [[ -n ${DONE_12:-} ]]; then
      note "Codex's MCP registration still passes port $p, so the MCP stage runs again"
      write_env DONE_12 "" >/dev/null
    fi
    p=$q
  fi
  AV_PORT=$p
  API=http://127.0.0.1:$p
  write_env AV_PORT "$p" >/dev/null
}

# ── stages ────────────────────────────────────────────────────────────────

s_preflight() {
  local os glibc missing=() pkgs=() c
  # shellcheck disable=SC1091
  os=$(. /etc/os-release && echo "$PRETTY_NAME")
  glibc=$(getconf GNU_LIBC_VERSION | awk '{ print $2 }')
  say "System: $os, glibc $glibc, $(nproc) CPUs, $(awk '/MemTotal/ { printf "%.0f GB", $2 / 1048576 }' /proc/meminfo)"
  if [[ $(printf '%s\n2.39\n' "$glibc" | sort -V | head -1) != 2.39 ]]; then
    warn "glibc $glibc is older than 2.39 (Ubuntu 24.04): the CI-built agentsview won't start here"
    return 1
  fi
  for c in curl jq gh git python3 systemd-run sha256sum ss; do
    command -v "$c" >/dev/null 2>&1 && continue
    missing+=("$c")
    case $c in
      ss) pkgs+=(iproute2) ;;
      systemd-run) pkgs+=(systemd) ;;
      sha256sum) pkgs+=(coreutils) ;;
      *) pkgs+=("$c") ;;
    esac
  done
  if ((${#missing[@]})); then
    warn "missing: ${missing[*]}"
    say "Install them, e.g.: sudo apt install ${pkgs[*]}"
    return 1
  fi
  if ! gh auth status >/dev/null 2>&1; then
    warn "gh isn't logged in: run gh auth login, then re-run this wizard"
    return 1
  fi
  mkdir -p "$SPIKE_DIR" "$REC" && chmod 700 "$SPIKE_DIR"
  say "Spike folder: $SPIKE_DIR"
  record "01-preflight" "## Desktop

$os, glibc $glibc, $(nproc) CPUs, $(awk '/MemTotal/ { printf "%.0f GB", $2 / 1048576 }' /proc/meminfo) RAM; GPU: $(lspci 2>/dev/null | awk -F': ' '/VGA|Display/ { print $2; exit }')
"
  pause "Press Enter to go on"
}

s_copilot_sync() {
  local f=$COPILOT_SETTINGS tmp state
  say "Copilot CLI copies local sessions to your GitHub account unless \"remoteExport\" is false, and"
  say "\"remoteSessions\": true turns that back on (§7). Do this before any test session."
  if copilot_sync_off; then
    say "Already off in $f."
  elif [[ -s $f ]] && ! jq empty "$f" 2>/dev/null; then
    warn "$f isn't plain JSON (comments?), so edit it by hand:"
    say "set \"remoteExport\": false, and \"remoteSessions\": false if it's there."
    pause "Press Enter when it's saved"
  elif confirm "Set \"remoteExport\": false (and \"remoteSessions\": false if it's true) in $f? A backup is kept."; then
    mkdir -p "$(dirname "$f")"
    [[ -f $f ]] && cp -p "$f" "$f.bak-$(date +%Y%m%d%H%M%S)"
    tmp=$(mktemp)
    # An empty or missing file starts from {}; the file is only replaced by a checked result.
    if { if [[ -s $f ]]; then cat "$f"; else echo '{}'; fi; } |
      jq '.remoteExport = false | if .remoteSessions == true then .remoteSessions = false else . end' >"$tmp" &&
      jq -e '.remoteExport == false and .remoteSessions != true' "$tmp" >/dev/null; then
      cat "$tmp" >"$f"
    else
      warn "couldn't update $f; it's unchanged"
    fi
    rm -f "$tmp"
  fi
  note "Don't turn on remote control in Copilot CLI (/remote on): that re-enables export too."
  if copilot_sync_off; then state=off; else state="still on"; fi
  record "02-copilot-sync" "## Copilot session sync

\`~/.copilot/settings.json\`: session sync $state (remoteExport false and remoteSessions not true).
"
  if [[ $state != off ]]; then
    warn "session sync is still on: Copilot CLI test sessions would be synced to GitHub"
    return 1
  fi
  printf '  %s✓%s session sync is off\n' "$GREEN" "$RESET"
  pause "Press Enter to go on"
}

s_install() {
  local tag
  tag=$(sed -n 's/^tag=//p' "$REPO_ROOT/vendor/agentsview.pin")
  if [[ -x $BIN ]] && "$BIN" --version 2>/dev/null | grep -q "agentsview $tag "; then
    say "Already installed: $("$BIN" --version)"
    confirm "Reinstall it?" || {
      record "03-install" "## agentsview

$("$BIN" --version), sha256 $(sha256sum "$BIN" | cut -c1-16)…
"
      return 0
    }
  fi
  say "Downloads the release, checks SHA256SUMS and the provenance attestation, installs to $(dirname "$BIN")."
  BIN_DIR=$(dirname "$BIN") "$REPO_ROOT/scripts/install-agentsview.sh" || return 1
  record "03-install" "## agentsview

$("$BIN" --version), sha256 $(sha256sum "$BIN" | cut -c1-16)…, checksum and attestation verified
"
  pause "Press Enter to go on"
}

s_probes() {
  local curl net_ok start fs net lo srv mode out key val q verdict sys_start="" sys_fs="" sys_net="" sys_lo=""
  curl=$(command -v curl)
  say "Can a user unit enforce the sandbox, or does agentsview need a system unit with User= (§4.1)?"
  say "Each probe runs as a transient user unit with the unit's sandbox settings."
  run_probe() { systemd-run --user --wait --quiet --collect "$@" >/dev/null 2>&1; }
  run_probe "$curl" -fsS -o /dev/null --max-time 10 https://example.com && net_ok=yes || net_ok=no
  if [[ $net_ok == no ]]; then
    warn "no network from a plain user unit, so the network probe can't tell anything; connect and re-run"
    return 1
  fi
  run_probe "${SANDBOX_PROPS[@]}" /bin/true && start=ok || start=failed
  rm -f "$PROBE_FILE"
  run_probe "${SANDBOX_PROPS[@]}" "$(command -v touch)" "$PROBE_FILE" && fs=no || fs=yes
  [[ -e $PROBE_FILE ]] && fs=no
  rm -f "$PROBE_FILE"
  run_probe "${SANDBOX_PROPS[@]}" "$curl" -fsS -o /dev/null --max-time 10 https://example.com && net=no || net=yes
  srv=$(loopback_server)
  run_probe "${SANDBOX_PROPS[@]}" "$curl" -fsS -o /dev/null --max-time 5 "http://127.0.0.1:$PROBE_PORT/" && lo=ok || lo=blocked
  kill "$srv" 2>/dev/null || true
  say "user unit: starts=$start · read-only home enforced=$fs · egress blocked=$net · loopback=$lo"
  if [[ $start == ok && $fs == yes && $net == yes && $lo == ok ]]; then
    mode=user
  else
    mode=system
    say ""
    say "A user unit can't confine agentsview here, so it needs a system unit with User=$USER."
    say "Check that a system unit does enforce it: run this in another terminal (it starts four"
    say "transient units as root, running as you, and writes their exit codes to a file):"
    out=$SPIKE_DIR/system-probe.txt
    rm -f "$out"
    srv=$(loopback_server)
    q=$(printf '%q ' "${SANDBOX_PROPS[@]}")
    prompt "sudo bash -c 'p() { systemd-run --wait --quiet --collect --uid=$USER $q \"\$@\" >/dev/null 2>&1; echo \$?; }; rm -f $PROBE_FILE; { echo start=\$(p /bin/true); echo write=\$(p $(command -v touch) $PROBE_FILE); echo net=\$(p $curl -fsS -o /dev/null --max-time 10 https://example.com); echo loopback=\$(p $curl -fsS -o /dev/null --max-time 5 http://127.0.0.1:$PROBE_PORT/); } >$out'"
    pause "Press Enter when it has finished"
    kill "$srv" 2>/dev/null || true
    if [[ -f $out ]]; then
      while IFS='=' read -r key val; do
        case $key in
          start) [[ $val == 0 ]] && sys_start=ok || sys_start=failed ;;
          write) [[ $val != 0 && ! -e $PROBE_FILE ]] && sys_fs=yes || sys_fs=no ;;
          net) [[ $val != 0 ]] && sys_net=yes || sys_net=no ;;
          loopback) [[ $val == 0 ]] && sys_lo=ok || sys_lo=blocked ;;
        esac
      done <"$out"
      say "system unit: starts=$sys_start · read-only home enforced=$sys_fs · egress blocked=$sys_net · loopback=$sys_lo"
    else
      warn "no $out, so the system unit wasn't checked"
    fi
    rm -f "$PROBE_FILE" 2>/dev/null || true
  fi
  verdict="**$mode unit**"
  if [[ $mode == system && ! ($sys_start == ok && $sys_fs == yes && $sys_net == yes && $sys_lo == ok) ]]; then
    verdict="none: the system unit wasn't confirmed to confine agentsview"
  fi
  record "04-probes" "## Sandbox probes (§4.1)

systemd $(systemctl --version | awk 'NR == 1 { print $2 }'), kernel $(uname -r), unprivileged userns restricted by AppArmor: $(cat /proc/sys/kernel/apparmor_restrict_unprivileged_userns 2>/dev/null || echo n/a)

| Unit | Starts with the sandbox | Read-only home enforced | Egress blocked | Loopback allowed |
|---|---|---|---|---|
| user | $start | $fs | $net | $lo |
| system, User=$USER | ${sys_start:-not run} | ${sys_fs:-not run} | ${sys_net:-not run} | ${sys_lo:-not run} |

Chosen: $verdict
"
  if [[ $verdict == none* ]]; then
    warn "a system unit doesn't confine agentsview either (or wasn't checked): stop here and report it"
    return 1
  fi
  write_env UNIT_MODE "$mode"
  pause "Press Enter to go on"
}

s_secrets() {
  local d dirs=() found mode p
  say "agentsview reads these agents' folders, so their credential files must be hidden from it."
  for d in "$HOME/.config/Cursor" "$HOME/.cursor" "$HOME/.copilot" "$HOME/.config/github-copilot" "$HOME/.config/Code"; do
    [[ -d $d ]] && dirs+=("$d")
  done
  found=""
  ((${#dirs[@]})) && found=$({
    find "${dirs[@]}" -maxdepth 4 \( -name workspaceStorage -o -name extensions -o -name 'Cache*' -o -name CachedData \
      -o -name logs -o -name session-state -o -name projects -o -name History \) -prune -o -type f \
      \( -iname '*auth*' -o -iname '*token*' -o -iname '*cred*' -o -iname '*secret*' -o -iname '*.pem' -o -iname '*.key' \
      -o -name hosts.json -o -name apps.json \) -print 2>/dev/null
    # -size -1024k, not -1M: find rounds sizes up to whole units, so -1M matches only empty files.
    find "${dirs[@]}" -maxdepth 2 -type f -name '*.json' -size -1024k -print0 2>/dev/null |
      xargs -0r grep -l -i -E '"[a-z_.-]*(tokens?|secret|password)"[[:space:]]*:' 2>/dev/null
  } | grep -v -E '/state\.vscdb(-|$)' | sort -u || true)
  : >"$SPIKE_DIR/inaccessible.txt"
  if [[ -z $found ]]; then
    say "No credential-looking files found in: ${dirs[*]:-none of the agent folders exist}"
  else
    say "Files that look like credentials (names or JSON token keys; contents not shown):"
    # The list comes in on fd 3, so confirm still reads the answers from the terminal.
    while IFS= read -r p <&3; do
      if [[ $p == *[[:space:]]* ]]; then
        warn "$p has a space in its path: add it to the unit by hand if it's a credential"
      elif confirm "Hide $p from agentsview?"; then
        printf '%s\n' "$p" >>"$SPIKE_DIR/inaccessible.txt"
      fi
    done 3<<<"$found"
  fi
  note "Cursor's state.vscdb holds tokens too, but agentsview has to read it (§4.1)."
  mode=$(cursor_db_mode)
  say "Cursor's state.vscdb journal mode: $mode"
  record "05-secrets" "## Credential files and Cursor's database

Hidden from agentsview besides the defaults (~/.ssh, ~/.gnupg, ~/.config/gh, ~/.codex/auth.json):
$(if [[ -s $SPIKE_DIR/inaccessible.txt ]]; then sed "s|^$HOME|- ~|" "$SPIKE_DIR/inaccessible.txt"; else echo '- none'; fi)

Other credential-looking files found: $(comm -23 <(printf '%s\n' "$found" | sed '/^$/d') <(sort "$SPIKE_DIR/inaccessible.txt") | sed "s|^$HOME|~|" | paste -sd ',' - | sed 's/,/, /g; s/^$/none/')

Cursor \`state.vscdb\` journal mode: $mode
"
  pause "Press Enter to go on"
}

s_unit() {
  local f pid home_opts data_opts counts prev stray i
  if [[ -z ${UNIT_MODE:-} ]]; then
    warn "run the sandbox probes stage first: it decides between a user and a system unit"
    return 1
  fi
  mkdir -p "$HOME/.agentsview"
  # With --replace the unit takes over a daemon that got there first; a unit of the other mode, left
  # from an earlier run, would take it back at its next start.
  if [[ $UNIT_MODE == system ]] && systemctl --user is-enabled --quiet agentsview.service 2>/dev/null; then
    warn "the user unit from an earlier run is still enabled"
    confirm "Disable and stop it (systemctl --user disable --now agentsview.service)" || return 1
    systemctl --user disable --now agentsview.service
  elif [[ $UNIT_MODE == user ]] && systemctl is-enabled --quiet agentsview.service 2>/dev/null; then
    warn "a system agentsview.service from an earlier run is still enabled; disable it in another terminal:"
    prompt "sudo systemctl disable --now agentsview.service"
    pause "Press Enter when it's done"
  fi
  stray=$(stray_daemons)
  [[ -z $stray ]] || note "agentsview outside the unit: $stray (the unit replaces a running daemon when it starts)"
  pick_port || return 1
  f=$SPIKE_DIR/agentsview.service
  unit_file >"$f"
  say "Unit ($UNIT_MODE), saved as $f:"
  sed 's/^/    /' "$f"
  if [[ $UNIT_MODE == user ]]; then
    confirm "Install it as ~/.config/systemd/user/agentsview.service and start it?" || return 1
    mkdir -p "$HOME/.config/systemd/user"
    cp "$f" "$HOME/.config/systemd/user/agentsview.service"
    systemctl --user daemon-reload
    systemctl --user enable agentsview.service
    systemctl --user restart agentsview.service
  else
    step "Install and (re)start it as root, in another terminal:"
    prompt "sudo install -m 0644 $f /etc/systemd/system/agentsview.service && sudo systemctl daemon-reload && sudo systemctl enable agentsview.service && sudo systemctl restart agentsview.service"
    pause "Press Enter when it's running"
  fi
  # agentsview binds the port only after its startup sync, which can take minutes on a long history.
  note "waiting for the API on $API, after the first sync of existing sessions (up to 30 min)…"
  for ((i = 1; i <= 900; i++)); do
    api_up && break
    ((i <= 5)) || sctl is-active --quiet agentsview.service || break
    ((i % 30)) || note "still waiting ($((i * 2 / 60)) min): $(jctl -n 1 --no-pager -o cat 2>/dev/null || true)"
    sleep 2
  done
  pid=$(sctl show -p MainPID --value agentsview.service 2>/dev/null || true)
  if ! api_up || ! sctl is-active --quiet agentsview.service || [[ ${pid:-0} == 0 ]]; then
    warn "the unit stopped, or its API didn't come up in 30 min; recent log:"
    jctl -n 20 --no-pager 2>/dev/null || true
    return 1
  fi
  home_opts=$(awk -v h="$(dirname "$HOME")" '$5 == h { o = $6 } END { print o }' "/proc/$pid/mountinfo" 2>/dev/null || true)
  data_opts=$(awk -v d="$HOME/.agentsview" '$5 == d { o = $6 } END { print o }' "/proc/$pid/mountinfo" 2>/dev/null || true)
  say "inside the unit: $(dirname "$HOME") mounted ${home_opts:-?}, ~/.agentsview ${data_opts:-?}"
  note "waiting for the first sync to settle (counts unchanged for 10 s, up to 5 min)…"
  prev=""
  for i in $(seq 1 30); do
    counts=$(agent_counts)
    [[ $counts == "$prev" ]] && break
    prev=$counts
    sleep 10
  done
  say "sessions per agent: $(paste -sd ',' - <<<"$counts" | sed 's/,/, /g')"
  stray=$(stray_daemons)
  [[ -z $stray ]] || warn "agentsview running outside the unit: $stray"
  record "06-unit" "## Sandboxed unit

$UNIT_MODE unit, active (pid $pid), API on port $AV_PORT. Inside it $(dirname "$HOME") is mounted \`${home_opts:-?}\` and ~/.agentsview \`${data_opts:-?}\`.
Existing sessions per agent after the first sync: $(paste -sd ',' - <<<"$counts" | sed 's/,/, /g').
agentsview processes outside the unit: ${stray:-none}
"
  pause "Press Enter to go on"
}

s_scratch() {
  local def=$HOME/agent-fabric-spike
  say "The test sessions run in a throwaway project with no secrets, so their recordings can later"
  say "become scrubbed fixtures (§7)."
  ask SCRATCH_DIR "Folder for it [$def]:" || true
  SCRATCH_DIR=${SCRATCH_DIR:-$def}
  SCRATCH_DIR=${SCRATCH_DIR/#\~/$HOME}
  [[ $SCRATCH_DIR == /* ]] || SCRATCH_DIR=$PWD/$SCRATCH_DIR
  if [[ -e $SCRATCH_DIR && ! -f $SCRATCH_DIR/.agent-fabric-spike ]] && [[ -n $(ls -A "$SCRATCH_DIR" 2>/dev/null) ]]; then
    warn "$SCRATCH_DIR exists and isn't empty; pick another folder"
    return 1
  fi
  mkdir -p "$SCRATCH_DIR"
  : >"$SCRATCH_DIR/.agent-fabric-spike"
  cat >"$SCRATCH_DIR/calc.py" <<'EOF'
RATE = 0.2


def with_tax(amount: float) -> float:
    return round(amount * (1 + RATE), 2)
EOF
  cat >"$SCRATCH_DIR/test_calc.py" <<'EOF'
import unittest

from calc import with_tax


class WithTaxTest(unittest.TestCase):
    def test_rate(self) -> None:
        self.assertEqual(with_tax(100), 125.0)


if __name__ == "__main__":
    unittest.main()
EOF
  printf '# agent-fabric spike\n\nThrowaway project for the capture spike. The test fails on purpose.\n' >"$SCRATCH_DIR/README.md"
  [[ -d $SCRATCH_DIR/.git ]] || git -C "$SCRATCH_DIR" init -q
  write_env SCRATCH_DIR "$SCRATCH_DIR"
  say "Created $SCRATCH_DIR (calc.py, test_calc.py with a failing test, README.md, git repo)."
  pause "Press Enter to go on"
}

